/** Resolve nama ikon dari database; null bila tidak ada di registry. */
export function resolveIcon(name?: string | null): IconComponent | null {
  if (!name) return null;
  return REGISTRY[name] ?? REGISTRY[name.replace(/[^A-Za-z0-9]/g, "")] ?? null;
}
